#!/usr/bin/env node
/**
 * Builds `docs/board.html`, the task board, from the two files that already own the facts:
 * `docs/CHANGELOG.md` (what is done) and `docs/BACKLOG.md` (what is ahead, closed or rejected),
 * plus the change folders under `docs/plans/` (what is in progress). The board restates nothing by
 * hand: a hand-kept board would be a third copy of the ledger, and two copies of one fact drift
 * (`FX-023`, `FX-027`). It is regenerated by the pre-commit hook and checked by `PR-API-10` (`CH-040`).
 *
 *   node scripts/board.mjs          # write docs/board.html
 *   node scripts/board.mjs check    # exit 1 if docs/board.html is stale
 */
import { execFileSync } from 'node:child_process';
import fs from 'node:fs';
import path from 'node:path';

const repoRoot = path.resolve(import.meta.dirname, '..');
const OUT = path.join(repoRoot, 'docs', 'board.html');

const read = (rel) => fs.readFileSync(path.join(repoRoot, rel), 'utf8');

/** Splits a markdown table row on unescaped pipes; `\|` inside a cell stays a pipe. */
function cells(line) {
  return line
    .trim()
    .replace(/^\|/, '')
    .replace(/\|$/, '')
    .split(/(?<!\\)\|/)
    .map((cell) => cell.trim().replace(/\\\|/g, '|'));
}

/** Every table under a `## heading`, as objects keyed by the header row. */
function tables(markdown) {
  const out = [];
  let heading = '';
  const lines = markdown.split(/\r?\n/);
  for (let i = 0; i < lines.length; i += 1) {
    const h = /^#{2,3}\s+(.*)$/.exec(lines[i]);
    if (h) heading = h[1].trim();
    if (lines[i].startsWith('|') && /^\|\s*-/.test(lines[i + 1] ?? '')) {
      const header = cells(lines[i]);
      const rows = [];
      let j = i + 2;
      for (; j < lines.length && lines[j].startsWith('|'); j += 1) {
        const values = cells(lines[j]);
        rows.push(Object.fromEntries(header.map((key, k) => [key, values[k] ?? ''])));
      }
      out.push({ heading, rows });
      i = j - 1;
    }
  }
  return out;
}

const escape = (text) =>
  text.replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');

/** The ledger's inline markdown: `code` and **bold**, nothing else. */
const inline = (text) =>
  escape(text)
    .replace(/`([^`]+)`/g, '<code>$1</code>')
    .replace(/\*\*([^*]+)\*\*/g, '<strong>$1</strong>');

/** A title: the first sentence, without markdown, cut at a word near 150 characters. */
function title(text) {
  const plain = text.replace(/\*\*Closed by[^*]*\*\*\s*/, '').replace(/[`*]/g, '');
  const first = plain.split(/(?<=[.!?])\s+(?=[A-Z(`])/)[0];
  if (first.length <= 150) return first;
  return first.slice(0, 150).replace(/\s+\S*$/, '') + '…';
}

function remoteUrl() {
  try {
    const url = execFileSync('git', ['remote', 'get-url', 'origin'], { cwd: repoRoot })
      .toString()
      .trim();
    return url.replace(/^git@github\.com:/, 'https://github.com/').replace(/\.git$/, '');
  } catch {
    return null;
  }
}

/**
 * A change is done once the ledger cites a commit that touched its folder: the ledger row names
 * the commit, not always the folder. A folder no cited commit touched is still in progress.
 */
function folderCommitCited(slug, changelog) {
  try {
    const hashes = execFileSync(
      'git',
      ['log', '--format=%h', '--abbrev=7', '--', `docs/plans/${slug}`],
      { cwd: repoRoot },
    )
      .toString()
      .split(/\s+/)
      .filter(Boolean);
    return hashes.some((hash) => changelog.includes(`\`${hash}`));
  } catch {
    return false;
  }
}

function collect() {
  const changelog = read('docs/CHANGELOG.md');
  const backlog = read('docs/BACKLOG.md');
  const done = [];

  for (const { heading, rows } of tables(changelog)) {
    const kind = /^Features/.test(heading)
      ? 'feature'
      : /^Process/.test(heading)
        ? 'process'
        : /^Defects/.test(heading)
          ? 'fix'
          : null;
    if (kind === null) continue;
    for (const row of rows) {
      if (!/^(FT|CH|FX)-\d+$/.test(row.ID)) continue;
      const text = row.What ?? row.Defect ?? '';
      const pathMarker = /Path: (full|short)[^|]*/.exec(text)?.[0] ?? '';
      done.push({
        id: row.ID,
        kind,
        date: row.Date,
        title: title(text),
        text,
        foundBy: row['Found by'] ?? '',
        commit: (row.Commit ?? '').replace(/`/g, ''),
        path: pathMarker,
      });
    }
  }

  const open = [];
  const closed = [];
  let rejected = [];
  for (const { heading, rows } of tables(backlog)) {
    if (/^Open/.test(heading)) {
      for (const row of rows) {
        if (!/^BL-\d+$/.test(row.ID)) continue;
        const closedBy = /^\*\*Closed by ([^*]+?)\.?\*\*/.exec(row.What);
        const item = {
          id: row.ID,
          priority: row.P,
          area: row.Area,
          title: title(row.What),
          text: row.What,
          dependsOn: row['Depends on'],
          conflicts: row['Conflicts with'],
        };
        if (closedBy) closed.push({ ...item, closedBy: closedBy[1].replace(/`/g, '') });
        else open.push(item);
      }
    } else if (/^Closed/.test(heading)) {
      for (const row of rows) {
        if (!/^BL-\d+$/.test(row.ID)) continue;
        closed.push({
          id: row.ID,
          area: '',
          title: title(row['What it was']),
          text: row['What it was'],
          closedBy: row['Closed by'].replace(/`/g, ''),
        });
      }
    } else if (/^Rejected/.test(heading)) {
      rejected = rows.map((row) => ({ title: row.What, why: row['Why rejected'] }));
    }
  }

  const plansDir = path.join(repoRoot, 'docs', 'plans');
  const inProgress = fs
    .readdirSync(plansDir, { withFileTypes: true })
    .filter((entry) => entry.isDirectory())
    .map((entry) => entry.name)
    .filter((slug) => !changelog.includes(slug) && !folderCommitCited(slug, changelog))
    .map((slug) => {
      const plan = path.join(plansDir, slug, `${slug}.plan.md`);
      const first = fs.existsSync(plan)
        ? (/^#\s+(.*)$/m.exec(fs.readFileSync(plan, 'utf8'))?.[1] ?? slug)
        : slug;
      return { slug, title: first };
    });

  const byNumber = (a, b) => Number(b.id.slice(3)) - Number(a.id.slice(3));
  done.sort((a, b) => (b.date === a.date ? byNumber(a, b) : b.date.localeCompare(a.date)));
  open.sort((a, b) => a.priority.localeCompare(b.priority) || byNumber(a, b));
  closed.sort(byNumber);

  return { done, open, closed, rejected, inProgress, remote: remoteUrl() };
}

function render({ done, open, closed, rejected, inProgress, remote }) {
  const count = (kind) => done.filter((item) => item.kind === kind).length;
  const latest = done[0]?.date ?? '';
  const kindLabel = { feature: 'Feature', process: 'Process', fix: 'Fix' };
  const commitLink = (hash) =>
    /^[0-9a-f]{7,40}$/.test(hash) && remote
      ? `<a href="${remote}/commit/${hash}" target="_blank" rel="noopener"><code>${hash}</code></a>`
      : `<code>${escape(hash)}</code>`;

  const backlogCard = (item) => `
      <details class="card" data-search="${escape(`${item.id} ${item.area} ${item.text}`.toLowerCase())}">
        <summary>
          <span class="id">${item.id}</span>
          <span class="chip area">${escape(item.area)}</span>
          <span class="title">${inline(item.title)}</span>
        </summary>
        <div class="body">
          <p>${inline(item.text)}</p>
          ${item.dependsOn ? `<p class="meta"><b>Depends on:</b> ${inline(item.dependsOn)}</p>` : ''}
          ${item.conflicts ? `<p class="meta"><b>Conflicts with:</b> ${inline(item.conflicts)}</p>` : ''}
        </div>
      </details>`;

  const column = (priority, label) => {
    const items = open.filter((item) => item.priority === priority);
    return `
    <section class="column p-${priority.toLowerCase()}">
      <h3>${label} <span class="count">${items.length}</span></h3>
      ${items.map(backlogCard).join('') || '<p class="empty">Nothing here.</p>'}
    </section>`;
  };

  const doneRow = (item) => `
      <details class="row ${item.kind}" data-kind="${item.kind}" data-search="${escape(`${item.id} ${item.text}`.toLowerCase())}">
        <summary>
          <span class="date">${escape(item.date)}</span>
          <span class="chip kind">${kindLabel[item.kind]}</span>
          <span class="id">${item.id}</span>
          <span class="title">${inline(item.title)}</span>
        </summary>
        <div class="body">
          <p>${inline(item.text)}</p>
          ${item.foundBy ? `<p class="meta"><b>Found by:</b> ${inline(item.foundBy)}</p>` : ''}
          <p class="meta"><b>Commit:</b> ${commitLink(item.commit)}</p>
        </div>
      </details>`;

  return `<!doctype html>
<html lang="en">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>PurpleSchool board</title>
<!-- Generated by scripts/board.mjs from docs/CHANGELOG.md, docs/BACKLOG.md and docs/plans/. Do not edit by hand. -->
<style>
:root {
  --bg: #f4f4f7; --surface: #ffffff; --text: #1d1b26; --muted: #5f5b70; --line: #e3e1ea;
  --accent: #6c4ee0; --p1: #c62828; --p2: #b26a00; --p3: #2e7d5b;
  --feature: #6c4ee0; --process: #2563a8; --fix: #c62828; --code: #f0eefa;
}
@media (prefers-color-scheme: dark) {
  :root {
    --bg: #14131a; --surface: #1e1c27; --text: #ecebf2; --muted: #a29fb3; --line: #2e2b3b;
    --accent: #a594ff; --p1: #ff7a7a; --p2: #f2b04f; --p3: #5fd3a0;
    --feature: #a594ff; --process: #7fb3ff; --fix: #ff7a7a; --code: #2a2738;
  }
}
* { box-sizing: border-box; }
body { margin: 0; background: var(--bg); color: var(--text);
  font: 15px/1.5 system-ui, -apple-system, "Segoe UI", Roboto, sans-serif; }
header { padding: 28px 16px 8px; max-width: 1280px; margin: 0 auto; }
h1 { margin: 0 0 4px; font-size: 26px; letter-spacing: -0.01em; }
.sub { color: var(--muted); margin: 0; }
main { max-width: 1280px; margin: 0 auto; padding: 0 16px 48px; }
.stats { display: grid; grid-template-columns: repeat(auto-fit, minmax(140px, 1fr)); gap: 12px; margin: 20px 0; }
.stat { background: var(--surface); border: 1px solid var(--line); border-radius: 12px; padding: 14px 16px; }
.stat .n { font-size: 28px; font-weight: 700; line-height: 1.1; }
.stat .l { color: var(--muted); font-size: 13px; }
.toolbar { display: flex; flex-wrap: wrap; gap: 8px; align-items: center; margin: 8px 0 16px; }
.tabs button, .filters button { border: 1px solid var(--line); background: var(--surface); color: var(--text);
  padding: 7px 14px; border-radius: 999px; cursor: pointer; font: inherit; }
.tabs button[aria-selected="true"], .filters button[aria-pressed="true"] { background: var(--accent); color: #fff; border-color: var(--accent); }
input[type=search] { flex: 1; min-width: 200px; padding: 8px 12px; border-radius: 999px;
  border: 1px solid var(--line); background: var(--surface); color: var(--text); font: inherit; }
.panel[hidden] { display: none; }
.board { display: grid; grid-template-columns: repeat(auto-fit, minmax(280px, 1fr)); gap: 16px; align-items: start; }
.column { background: color-mix(in srgb, var(--surface) 60%, transparent); border: 1px solid var(--line); border-radius: 14px; padding: 12px; }
.column h3 { margin: 4px 4px 12px; font-size: 15px; display: flex; align-items: center; gap: 8px; }
.column h3::before { content: ""; width: 10px; height: 10px; border-radius: 50%; background: var(--accent); }
.p-p1 h3::before { background: var(--p1); } .p-p2 h3::before { background: var(--p2); } .p-p3 h3::before { background: var(--p3); }
.count { margin-left: auto; color: var(--muted); font-weight: 500; }
.card, .row { background: var(--surface); border: 1px solid var(--line); border-radius: 10px; margin-bottom: 8px; }
.card summary, .row summary { list-style: none; cursor: pointer; padding: 10px 12px; display: flex; flex-wrap: wrap; gap: 6px 8px; align-items: baseline; }
.card summary::-webkit-details-marker, .row summary::-webkit-details-marker { display: none; }
.card[open], .row[open] { border-color: var(--accent); }
.title { flex: 1 1 100%; }
.row .title { flex: 1 1 320px; }
.id { font-weight: 700; font-variant-numeric: tabular-nums; }
.date { color: var(--muted); font-variant-numeric: tabular-nums; min-width: 88px; }
.chip { font-size: 12px; padding: 1px 8px; border-radius: 999px; border: 1px solid var(--line); color: var(--muted); }
.row.feature .kind { color: var(--feature); border-color: var(--feature); }
.row.process .kind { color: var(--process); border-color: var(--process); }
.row.fix .kind { color: var(--fix); border-color: var(--fix); }
.body { padding: 0 12px 12px; border-top: 1px solid var(--line); }
.body p { margin: 10px 0 0; overflow-wrap: anywhere; }
.meta { color: var(--muted); font-size: 14px; }
code { background: var(--code); padding: 0 4px; border-radius: 4px; font-size: 0.9em; }
a { color: var(--accent); }
.empty { color: var(--muted); padding: 4px; }
.progress .card { border-left: 4px solid var(--accent); }
table { width: 100%; border-collapse: collapse; background: var(--surface); border-radius: 10px; overflow: hidden; }
td, th { text-align: left; vertical-align: top; padding: 10px 12px; border-bottom: 1px solid var(--line); }
th { color: var(--muted); font-weight: 600; font-size: 13px; }
.hidden { display: none; }
@media (max-width: 600px) { .date { min-width: 0; } }
</style>
</head>
<body>
<header>
  <h1>PurpleSchool board</h1>
  <p class="sub">Built from the ledger and the backlog by <code>scripts/board.mjs</code>. Latest ledger entry: ${escape(latest)}.</p>
</header>
<main>
  <div class="stats">
    <div class="stat"><div class="n">${inProgress.length}</div><div class="l">In progress</div></div>
    <div class="stat"><div class="n">${open.length}</div><div class="l">Open in backlog</div></div>
    <div class="stat"><div class="n" style="color:var(--p1)">${open.filter((i) => i.priority === 'P1').length}</div><div class="l">P1 — blocking</div></div>
    <div class="stat"><div class="n">${count('feature')}</div><div class="l">Features shipped</div></div>
    <div class="stat"><div class="n">${count('process')}</div><div class="l">Process changes</div></div>
    <div class="stat"><div class="n">${count('fix')}</div><div class="l">Defects fixed</div></div>
  </div>

  <div class="toolbar">
    <div class="tabs" role="tablist">
      <button role="tab" aria-selected="true" data-tab="board">Board</button>
      <button role="tab" aria-selected="false" data-tab="done">Done</button>
      <button role="tab" aria-selected="false" data-tab="closed">Closed backlog</button>
      <button role="tab" aria-selected="false" data-tab="rejected">Rejected</button>
    </div>
    <input type="search" id="q" placeholder="Search by ID or text…" aria-label="Search">
  </div>

  <div class="panel" id="board">
    <div class="board">
      <section class="column progress">
        <h3>In progress <span class="count">${inProgress.length}</span></h3>
        ${
          inProgress
            .map(
              (item) => `
        <div class="card"><div class="body" style="border:0;padding:10px 12px">
          <span class="id">${escape(item.slug)}</span>
          <p>${inline(item.title)}</p>
          <p class="meta">A change folder in <code>docs/plans/${escape(item.slug)}/</code> with no ledger entry yet.</p>
        </div></div>`,
            )
            .join('') ||
          '<p class="empty">No change is open: every change folder has its ledger entry.</p>'
        }
      </section>
      ${column('P1', 'P1 · blocks production or the next feature')}
      ${column('P2', 'P2 · needed, can wait')}
      ${column('P3', 'P3 · improvement in passing')}
    </div>
  </div>

  <div class="panel" id="done" hidden>
    <div class="toolbar filters">
      <button aria-pressed="true" data-kind="all">All</button>
      <button aria-pressed="false" data-kind="feature">Features</button>
      <button aria-pressed="false" data-kind="process">Process</button>
      <button aria-pressed="false" data-kind="fix">Fixes</button>
    </div>
    ${done.map(doneRow).join('')}
  </div>

  <div class="panel" id="closed" hidden>
    ${closed
      .map(
        (item) => `
      <details class="card" data-search="${escape(`${item.id} ${item.text}`.toLowerCase())}">
        <summary><span class="id">${item.id}</span><span class="chip">closed by ${escape(item.closedBy)}</span><span class="title">${inline(item.title)}</span></summary>
        <div class="body"><p>${inline(item.text)}</p></div>
      </details>`,
      )
      .join('')}
  </div>

  <div class="panel" id="rejected" hidden>
    <table>
      <thead><tr><th>Proposal</th><th>Why rejected</th></tr></thead>
      <tbody>
      ${rejected.map((item) => `<tr data-search="${escape(`${item.title} ${item.why}`.toLowerCase())}"><td>${inline(item.title)}</td><td>${inline(item.why)}</td></tr>`).join('')}
      </tbody>
    </table>
  </div>
</main>
<script>
const tabs = document.querySelectorAll('[data-tab]');
tabs.forEach((tab) => tab.addEventListener('click', () => {
  tabs.forEach((t) => t.setAttribute('aria-selected', String(t === tab)));
  document.querySelectorAll('.panel').forEach((p) => { p.hidden = p.id !== tab.dataset.tab; });
  try { localStorage.setItem('board-tab', tab.dataset.tab); } catch {}
}));
try { const saved = localStorage.getItem('board-tab'); if (saved) document.querySelector('[data-tab="' + saved + '"]')?.click(); } catch {}
let kind = 'all';
const apply = () => {
  const q = document.getElementById('q').value.trim().toLowerCase();
  document.querySelectorAll('[data-search]').forEach((el) => {
    const byText = !q || el.dataset.search.includes(q);
    const byKind = !el.dataset.kind || kind === 'all' || el.dataset.kind === kind;
    el.classList.toggle('hidden', !(byText && byKind));
  });
};
document.getElementById('q').addEventListener('input', apply);
document.querySelectorAll('[data-kind]').forEach((b) => b.tagName === 'BUTTON' && b.addEventListener('click', () => {
  kind = b.dataset.kind;
  document.querySelectorAll('.filters button').forEach((x) => x.setAttribute('aria-pressed', String(x === b)));
  apply();
}));
</script>
</body>
</html>
`;
}

const html = render(collect());

if (process.argv[2] === 'check') {
  const current = fs.existsSync(OUT) ? fs.readFileSync(OUT, 'utf8') : '';
  if (current !== html) {
    console.error('docs/board.html is stale: run `pnpm board` and commit the result');
    process.exit(1);
  }
  console.log('docs/board.html matches the ledger and the backlog.');
} else {
  fs.writeFileSync(OUT, html);
  console.log('Wrote docs/board.html.');
}
